#include <stdio.h>

static int sum(const int *values, size_t count) {
    int total = 0;

    for (size_t i = 0; i < count; i++) {
        total += values[i];
    }

    return total;
}

int main(void) {
    int readings[] = {4, 8, 15, 16, 23, 42};

    printf("Total: %d\n", sum(readings, 6));
    return 0;
}

